    "lottery_name" text NOT NULL,
    "results" text[] NOT NULL,
    "source_url" text NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);
COMMENT ON COLUMN "public"."lottery_api_results"."draw_date" IS 'วันที่ออกรางวัล';
COMMENT ON COLUMN "public"."lottery_api_results"."draw_time" IS 'เวลาที่ออกรางวัล';
COMMENT ON COLUMN "public"."lottery_api_results"."country" IS 'ประเทศต้นกำเนิด';
COMMENT ON COLUMN "public"."lottery_api_results"."lottery_name" IS 'ชื่อหวย';
COMMENT ON COLUMN "public"."lottery_api_results"."results" IS 'ผลลัพธ์การออกรางวัล';
