    "type_number" text NOT NULL,
    "action" text NOT NULL CHECK (action = ANY (ARRAY['half'::text, 'close'::text])),
    "reason" text,
    "is_manual" boolean DEFAULT false,
    "draw_date" date NOT NULL,
    "risk_percentage" numeric,
    "created_at" timestamptz DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);

CREATE TABLE "public"."management_fee_cycles" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "cycle_start_date" date NOT NULL,
    "cycle_end_date" date NOT NULL,
    "cycle_number" integer NOT NULL,
    "total_profit_loss" numeric NOT NULL DEFAULT 0,
    "management_fee_rate" numeric NOT NULL DEFAULT 0.05 CHECK (management_fee_rate >= 0::numeric AND management_fee_rate <= 1::numeric),
    "management_fee_amount" numeric NOT NULL DEFAULT 0,
    "total_net_amount" numeric NOT NULL DEFAULT 0,
    "remaining_balance" numeric NOT NULL DEFAULT 0,
    "is_paid" boolean NOT NULL DEFAULT false,
    "paid_at" timestamptz,
    "payment_reference" text,
    "notes" text,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "auto_created" boolean DEFAULT false,
    "created_by_scheduler" boolean DEFAULT false,
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."management_fee_cycles" ADD CONSTRAINT "management_fee_daily_records_cycle_id_fkey" FOREIGN KEY ("cycle_id") REFERENCES "public"."management_fee_cycles" ("id");

CREATE TABLE "public"."management_fee_daily_records" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "cycle_id" uuid,
    "record_date" date NOT NULL,
    "daily_profit_loss" numeric NOT NULL DEFAULT 0,
    "daily_net_amount" numeric NOT NULL DEFAULT 0,
    "daily_management_fee" numeric NOT NULL DEFAULT 0,
    "cumulative_profit_loss" numeric NOT NULL DEFAULT 0,
    "cumulative_net_amount" numeric NOT NULL DEFAULT 0,
    "cumulative_management_fee" numeric NOT NULL DEFAULT 0,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."management_fee_daily_records" ADD CONSTRAINT "management_fee_daily_records_cycle_id_fkey" FOREIGN KEY ("cycle_id") REFERENCES "public"."management_fee_cycles" ("id");

CREATE TABLE "public"."management_fee_scheduler_settings" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "is_enabled" boolean DEFAULT true,
    "cycle_days" integer DEFAULT 7,
    "auto_create_next_cycle" boolean DEFAULT true,
    "last_cycle_created_at" timestamptz,
    "next_cycle_date" date,
    "created_at" timestamptz DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);

CREATE TABLE "public"."scheduled_tasks" (
    "id" text NOT NULL,
    "name" text NOT NULL,
    "type" text NOT NULL CHECK (type = ANY (ARRAY['scrape'::text, 'send'::text, 'cleanup'::text])),
    "scheduled_time" time NOT NULL,
    "draw_time" time NOT NULL,
    "status" text NOT NULL DEFAULT 'pending'::text CHECK (status = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'failed'::text])),
    "last_run" timestamptz,
    "next_run" timestamptz NOT NULL,
    "schedule_id" integer,
    "lottery_sub_type_id" integer,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."scheduled_tasks" ADD CONSTRAINT "task_logs_task_id_fkey" FOREIGN KEY ("task_id") REFERENCES "public"."scheduled_tasks" ("id");

CREATE TABLE "public"."scrape_schedules" (
    "id" integer NOT NULL DEFAULT nextval('scrape_schedules_id_seq'::regclass),
    "drawing_time" time NOT NULL UNIQUE,
    "last_run" timestamp,
    "status" varchar,
    "next_run" timestamp,
    PRIMARY KEY ("id")
);

CREATE TABLE "public"."status_change_history" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "ticket_id" uuid NOT NULL,
    "user_id" uuid NOT NULL,
    "old_status" text NOT NULL,
    "new_status" text NOT NULL,
    "changed_at" timestamptz DEFAULT now(),
    "created_at" timestamptz DEFAULT now(),
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."status_change_history" ADD CONSTRAINT "status_change_history_ticket_id_fkey" FOREIGN KEY ("ticket_id") REFERENCES "public"."lottery_tickets" ("id");
ALTER TABLE "public"."status_change_history" ADD CONSTRAINT "status_change_history_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."profiles" ("id");

CREATE TABLE "public"."task_logs" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "task_id" text NOT NULL,
    "task_name" text NOT NULL,
    "task_type" text NOT NULL,
    "status" text NOT NULL CHECK (status = ANY (ARRAY['completed'::text, 'failed'::text])),
    "error_message" text,
    "execution_time" timestamptz NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."task_logs" ADD CONSTRAINT "task_logs_task_id_fkey" FOREIGN KEY ("task_id") REFERENCES "public"."scheduled_tasks" ("id");

CREATE TABLE "public"."task_queue" (
    "id" bigint NOT NULL DEFAULT nextval('task_queue_id_seq'::regclass),
    "task_id" text NOT NULL,
    "task_type" text NOT NULL,
    "drawing_time" time,
    "lottery_sub_type_id" integer,
    "status" text NOT NULL DEFAULT 'queued'::text CHECK (status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text])),
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "attempts" integer DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE "public"."ticket_purchase_items" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "ticket_purchase_id" uuid,
    "ticket_sub_type_id" uuid,
    "ticket_number" text NOT NULL,
    "amount" numeric NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."ticket_purchase_items" ADD CONSTRAINT "ticket_purchase_items_ticket_purchase_id_fkey" FOREIGN KEY ("ticket_purchase_id") REFERENCES "public"."ticket_purchases" ("id");

CREATE TABLE "public"."ticket_purchases" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "user_id" uuid NOT NULL,
    "ticket_set_number" text NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "deleted_at" timestamptz,
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."ticket_purchases" ADD CONSTRAINT "ticket_purchases_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "auth"."users" ("id");
ALTER TABLE "public"."ticket_purchases" ADD CONSTRAINT "ticket_purchase_items_ticket_purchase_id_fkey" FOREIGN KEY ("ticket_purchase_id") REFERENCES "public"."ticket_purchases" ("id");

CREATE TABLE "public"."ticket_sub_types" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "name" varchar NOT NULL,
    "description" text,
    "created_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("id")
);

CREATE TABLE "public"."user_roles" (
    "user_id" uuid NOT NULL,
    "role" text NOT NULL,
    "updated_at" timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
    PRIMARY KEY ("user_id")
);
